import{d,C as n,o as g,c as h,a3 as e,E as s,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第七章","description":"《正易心法》第七章——天地万物，理有未明，观于卦脉则理昭然：坎兑艮离四画推知月为地气、日为天气、山自天来、雨从地出，卦画如浑仪。","frontmatter":{"title":"正易心法·第七章","description":"《正易心法》第七章——天地万物，理有未明，观于卦脉则理昭然：坎兑艮离四画推知月为地气、日为天气、山自天来、雨从地出，卦画如浑仪。","category":"guide","aliases":["正易心法第七章","观于卦脉","卦脉"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-07.md","filePath":"yijing/zheng-yi-xin-fa/chapter-07.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-07.md"},x=d({...c,setup(u){const o=[{id:"z7-01",label:"一、观于卦脉",showLabel:!0,sentences:[["天地万物，理有未明。观于",{text:"卦脉",glossary:"guamai"},"，理则",{text:"昭然",glossary:"zhaoran"},"。"]],note:["天地万物的道理，有许多尚未明了；但观察卦脉，这些道理便昭然若揭。（这是全书第二个核心概念：第一章讲「落处」，本章讲「卦脉」——落处是义理落在哪里，卦脉是阴阳如何流到那里。）"]},{id:"z7-02",label:"二、卦脉审",showLabel:!0,sentences:[["卦脉，为运动流行自然之理也。卦脉",{text:"审",glossary:"shen"},"，则天地万物之理得矣。"]],note:["所谓卦脉，是阴阳运动流行的自然之理；把卦脉审察清楚，天地万物的道理便可得到。（「脉」字极妙：人体有血脉，气血在其中流行；卦画有卦脉，阴阳在其中运动——两者是同一件事的两个层面，呼应第二章的「血气流行」。）"]},{id:"z7-03",label:"三、四画观法",showLabel:!0,sentences:[["如观坎画，则知月为地之气；观离画，则知日为天之气；观艮画，则知山自天来；观兑画，则知雨从地出。"]],note:["比如：观坎卦之画，便知月亮是地气所生；观离卦之画，便知太阳是天气所成；观艮卦之画，便知山是从天上降来的；观兑卦之画，便知雨是从地下升出的。四个结论都由卦画的爻位结构推出——坎（阳陷阴中）如月，外阴内阳；离（阴附阳中）如日，外阳内阴；艮（一阳在上）如山，天气自上凝结；兑（一阴在上）如雨，地气上升为阴。"]},{id:"z7-04",label:"四、观叠交",showLabel:!0,sentences:[["观",{text:"叠交",glossary:"diejiao"},"，则知",{text:"闰余之数",glossary:"runyu"},"；"]],note:["观卦画的叠交，便知历法闰余之数的道理。（坎为月、离为日，日月交叠运行：阴历一年约 354 天，阳历一年约 365 天，差约 11 天，故三年一闰、五年二闰、十九年七闰——闰余之数正是从「日月叠交」中自然显现的。）"]},{id:"z7-05",label:"五、观交体",showLabel:!0,sentences:[["观",{text:"交体",glossary:"jiaoti"},"，则知",{text:"造化之原",glossary:"zaohua"},"。"]],note:["观卦画的交体，便知造化生成的根源。（交体即上下卦交叠而成的整体，最典型者是坎离相交：坎☵与离☲交叠为既济（水火既济，造化完成之象）或未济（火水未济，造化未完成之象）。）"]},{id:"z7-06",label:"六、浑仪之器",showLabel:!0,sentences:[["凡此卦画，皆所以写天地万物之理于目前，亦若",{text:"浑仪",glossary:"hunyi"},"之器也。"]],note:["凡此种种卦画，都是把天地万物的道理写在眼前，就像浑天仪这件仪器一样。（浑天仪以铜环模拟天球运行，是天地运行的物理模型；卦画模拟阴阳运动，是天地的符号模型——都可以操作、可以观测、可以推演。麻衣以此说明：卦画不是抽象符号，而是天地运行的直接模型。）"]}],r=[{id:"guamai",term:"卦脉",pinyin:"guà mài",meaning:"卦的脉络，即卦画中阴阳流动的运动轨迹。本章核心词，与第一章「落处」并列，构成方法论的两大支柱。"},{id:"zhaoran",term:"昭然",pinyin:"zhāo rán",meaning:"明白显著，清晰可见。"},{id:"shen",term:"审",pinyin:"shěn",meaning:"仔细察看、明辨。审察卦脉，即细观卦画结构。"},{id:"diejiao",term:"叠交",pinyin:"dié jiāo",meaning:"卦画的重叠交错，指上下卦交叠形成的结构关系。"},{id:"runyu",term:"闰余之数",pinyin:"rùn yú zhī shù",meaning:"历法中多余的天数。阴历与阳历的差值，用来置闰。"},{id:"jiaoti",term:"交体",pinyin:"jiāo tǐ",meaning:"交叠的卦体，上下卦交叉形成的整体结构。"},{id:"zaohua",term:"造化之原",pinyin:"zào huà zhī yuán",meaning:"造化的根源，天地生成万物的根本原理。"},{id:"hunyi",term:"浑仪",pinyin:"hún yí",meaning:"浑天仪，古代天文观测仪器，以铜环模拟天球运动。"}];return(b,t)=>{const i=n("DaoTextReading"),l=n("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e("",17)),s(i,{colophon:"观于卦脉 · 四画观法 · 叠交闰余 · 浑仪之器",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第七章原文",sections:o,glossary:r}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「观离画，则知雨从地出」「观叠交，则知曰为天之气」两处疑有传抄之误——离为日（非雨），「曰」当为「日」；参考第一章「坎得乾中爻，故月自天之中而运」的用法，此处顺序当为坎（月）、离（日）、艮（山）、兑（雨）。此类讹误在古籍中常见，正是训诂学存在的理由之一；遇到文意不通处，不可盲诵，须回卦画结构验证。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"卦脉",pinyin:["guà","mài"],meaning:"卦画中阴阳流动的运动轨迹。与第一章「落处」并列，是麻衣方法论的第二支柱。"},{term:"四画观法",pinyin:["sì","huà"],meaning:"由卦画的爻位结构推知自然现象：坎（阳陷阴中）为月、离（阴附阳中）为日、艮（一阳在上）为山、兑（一阴在上）为雨。"},{term:"叠交 · 闰余",pinyin:["dié","jiāo"],meaning:"日月交叠运行，一年差约十一日，故三年一闰——闰余之数从「坎离叠交」中自然显现。"},{term:"交体",pinyin:["jiāo","tǐ"],meaning:"上下卦交叠而成的整体。坎离相交为既济／未济，是造化完成与未完成的两个象征。"},{term:"浑仪之器",pinyin:["hún","yí"],meaning:"浑天仪以铜环模拟天球；卦画模拟阴阳运动。麻衣以此说明卦画是天地的直接模型，不是抽象符号。"}]}),t[3]||(t[3]=e("",30))])}}});export{y as __pageData,x as default};
